import itertools

def solution():
    """Four distinct integers a, b, c, and d have the property that when added in pairs, the sums 10, 18, 19, 20, 21, and 29 are obtained. Find the four integers in increasing order."""
    sums = [10, 18, 19, 20, 21, 29]
    for a, b, c, d in itertools.permutations(range(1, 100), 4):
        if sorted([a+b, a+c, a+d, b+c, b+d, c+d]) == sorted(sums):
            return f"{a}, {b}, {c}, {d}"
    return "No solution found"

