    '''
    # Step 1: Define a function that calculates the total cost for a given number of tickets t.
    def calculate_cost(t):
        if t <= 60:
            return t * 70
        else:
            return 60 * 70 + (t - 60) * (70 - (t - 60))

    # Step 2: Define a function that calculates the profit for a given number of tickets t and a target profit of $4200.
    def calculate_profit(t):
        return calculate_cost(t) - (t * 70)

    # Step 3: Use a loop to find the largest t that results in a profit greater than $4200.
