def solution():
    '''
    Create a function solution that returns the answer of the following question: Of the four points $(2,2)$, $(9,11)$, $(5,7)$, and $(11,17)$, three lie on the same line. Which point is not on the line? 

    Let's think step by step.
    1. Calculate the slope between each pair of points.
    2. If the slope between any two pairs of points is the same, then those three points lie on the same line.
    3. Return the point that does not have the same slope with the other two points.
    4. If there are multiple points that do not have the same slope, return all of them.
    5. If all points have the same slope, return an empty list or a message indicating that all points lie on the same line.
    '''
    points = [(2, 2), (9, 11), (5, 7), (11, 17)]

    # Helper function to calculate the slope between two points
    def slope(p1, p2):
        if p1[0] == p2[0]:  # To avoid division by zero
            return float('inf')
        return (p2[1] - p1[1]) / (p2[0] - p1[0])

    # Calculate the slopes between each pair of points
    slopes = {}
    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            s = slope(points[i], points[j])
            if s not in slopes:
                slopes[s] = [points[i], points[j]]
            else:
                slopes[s].append(points[i])
                slopes[s].append(points[j])

    # Find the point(s) that do not have the same slope with the other two points
    not_on_line = []
    for s, pts in slopes.items():
        if len(pts) == 2:
            not_on_line.extend(pts)

    # Remove duplicates and return the result
    return list(set(not_on_line))

