def solution():
    '''
    Create a function solution that returns the answer of the following question: What is the greatest prime factor of the sum of the arithmetic sequence $1 + 2 + 3 + \cdots + 80$? 

    Let's think step by step.
    1. Calculate the sum of the arithmetic sequence.
    2. Find the prime factors of the sum.
    3. Return the greatest prime factor.
    4. Create a helper function to check if a number is prime.
    5. Create another helper function to find the prime factors of a number.
    6. Use these helper functions in the main function.
    '''
    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    def prime_factors(n):
        factors = []
        i = 2
        while i * i <= n:
            if n % i:
                i += 1
            else:
                n //= i
                factors.append(i)
        if n > 1:
            factors.append(n)
        return factors

    # Step 1: Calculate the sum of the arithmetic sequence
    n = 80
    sum_sequence = n * (n + 1) // 2

    # Step 2: Find the prime factors of the sum
    prime_factors_list = prime_factors(sum_sequence)

    # Step 3: Return the greatest prime factor
    if prime_factors_list:
        return max(prime_factors_list)
    else:
        return -1  # This should not happen as the sum of 1 to 80 is always positive

