import itertools
import sympy as sp

def solution():
    suits = ['hearts', 'diamonds', 'clubs', 'spades']
    cards_per_suit = 13
    total_cards = 52
    cards_drawn = 5

    # Calculate the total number of ways to draw 5 cards from 52
    total_ways = sp.binomial(total_cards, cards_drawn)

    # Calculate the number of ways to draw cards from at least three suits
    three_suits_ways = 0
    four_suits_ways = 0

    for suit_combination in itertools.combinations(suits, 3):
        for cards_in_suits in itertools.product(*[range(1, cards_per_suit+1) for _ in suit_combination], repeat=cards_drawn):
            if sum(cards_in_suits) == cards_drawn:
                three_suits_ways += 1

    for suit_combination in itertools.combinations(suits, 4):
        for cards_in_suits in itertools.product(*[range(1, cards_per_suit+1) for _ in suit_combination], repeat=cards_drawn):
            if sum(cards_in_suits) == cards_drawn:
                four_suits_ways += 1

    # Calculate the probability
    probability = (three_suits_ways + four_suits_ways) / total_ways
    return sp.simplify(probability)

