        return list(zip(*piece[::-1]))

    def flip(piece):
        return [row[::-1] for row in piece]

    def is_valid(board, piece, x, y):
        for i in range(3):
            for j in range(3):
                if piece[i][j] == 1 and (board[x+i][y+j] == 0 or board[x+i][y+j] == 2):
