    # The lateral surface area of a full cylinder is 2 * pi * radius * height
    # Since we have a half-cylinder, we take half of that
    lateral_area = 0.5 * 2 * 3.14159 * 6 * 10

    # Step 2: Calculate the area of the two circular bases.
    # The area of a full circle is pi * radius^2
    # Since we have two bases, we multiply by 2
    base_area = 2 * 3.14159 * 6**2

    # Step 3: Add the areas from step 1 and step 2 to get the total surface area.
    total_surface_area = lateral_area + base_area

