def solution():
    '''
    Create a function solution that returns the answer of the following question: There are two different isosceles triangles whose side lengths are integers and whose areas are $120.$ One of these two triangles, $\triangle XYZ,$ is shown. Determine the perimeter of the second triangle.

[asy]
draw((0,0)--(30,0)--(15,-8)--cycle,black+linewidth(1));
label("$X$",(0,0),W);
label("$Y$",(15,-8),S);
label("$Z$",(30,0),E);
