label("17",(15,-8)--(30,0),SE);
[/asy] 

    Let's think step by step.
    1. Calculate the base and height of the given isosceles triangle $\triangle XYZ$ using Heron's formula and the area formula.
    2. Use the base and height to find the side lengths of $\triangle XYZ$.
    3. Write a function to check if a triangle with given side lengths is isosceles and has an area of 120.
    4. Loop through possible side lengths for the second triangle, checking if it is isosceles and has an area of 120.
    5. If found, calculate the perimeter of the second triangle.
    6. Return the perimeter of the second triangle.
    '''
    import math

    # Step 1: Calculate the base and height of the given isosceles triangle XYZ
    base_XYZ = 30
    height_XYZ = 17
    area_XYZ = 120

    # Step 2: Use the base and height to find the side lengths of XYZ
    side_XYZ = math.sqrt((base_XYZ/2)**2 + height_XYZ**2)

    # Step 3: Write a function to check if a triangle with given side lengths is isosceles and has an area of 120
    def is_triangle_with_area_120(a, b, c):
        s = (a + b + c) / 2
        area = math.sqrt(s * (s - a) * (s - b) * (s - c))
        return area == 120 and (a == b or b == c or a == c)

    # Step 4: Loop through possible side lengths for the second triangle
    for a in range(1, 100):
        for b in range(a, 100):
            for c in range(b, 100):
                if is_triangle_with_area_120(a, b, c) and a != side_XYZ and b != side_XYZ and c != side_XYZ:
                    # Step 5: If found, calculate the perimeter of the second triangle
                    perimeter = a + b + c
                    return perimeter

    # If no such triangle is found, return -1
    return -1

