def solution():
    '''
    Create a function solution that returns the answer of the following question: The figure shown is called a trefoil and is constructed by drawing circular sectors about sides of the congruent equilateral triangles. What is the area of a trefoil whose horizontal base has length 2?

[asy]
unitsize(1cm);
path a =(-1.73,1)..(-1,1.73)--(-2,0)..cycle;
draw(a,linewidth(0.7));
path b= (1.73,1)..(2,0)--(1,1.73)..cycle;
