def solution():
    """Find the area of the square with four circles of radius 1 tangent to two sides and externally tangent to a circle of radius 2."""
    radius_small_circle = 1
    radius_large_circle = 2

    # The diagonal of the square is the sum of the diameters of the small circle and the large circle
    diagonal = 2 * radius_small_circle + 2 * radius_large_circle

    # The side of the square is half the diagonal
    side = diagonal / math.sqrt(2)

