import sympy as sp

def solution():
    x, y = sp.symbols('x y')

    # Define the equations of the lines
    line1 = sp.Eq(y, 0)
    line2 = sp.Eq(y, x + 4)
    line3 = sp.Eq(x + 3*y, 12)

    # Find the intersection points of the lines
    intersection1 = sp.solve((line1, line2), (x, y))
    intersection2 = sp.solve((line1, line3), (x, y))
    intersection3 = sp.solve((line2, line3), (x, y))

    # Calculate the area of the triangle using the Shoelace formula
    x_coords = [intersection1[x], intersection2[x], intersection3[x]]
    y_coords = [intersection1[y], intersection2[y], intersection3[y]]
    area = 0.5 * abs(sum(x_coords[i] * y_coords[i + 1] for i in range(3)) - sum(y_coords[i] * x_coords[i + 1] for i in range(3)))

    return area
