def solution():
    '''
    Create a function solution that returns the answer of the following question: Find $AX$ in the diagram if $CX$ bisects $\angle ACB$. [asy]
import markers;

real t=1-.32;
pair A=(-4.07,0);
pair B=(40.008,0);
pair C=(0,20.616);
pair X=t*A+(1-t)*B;

