def solution():
    '''
    Create a function solution that returns the answer of the following question: The roots of the polynomial \[x^3 - 52x^2 + 581x - k\]are distinct prime numbers. Find $k.$ 

    Let's think step by step.
    1. Let the three distinct prime roots be $p,$ $q,$ and $r.$
    2. By Vieta's formulas, $p + q + r = 52$ and $pqr = k.$
    3. List all possible combinations of three distinct prime numbers that sum to 52.
    4. For each combination, calculate the product $pqr.$
    5. The value of $k$ is the product that corresponds to the given polynomial.
    6. Return the value of $k.$
    '''
    # Step 1: Define a helper function to check if a number is prime
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    # Step 2: Generate all possible combinations of three distinct prime numbers that sum to 52
    prime_numbers = [i for i in range(2, 52) if is_prime(i)]
    prime_combinations = []
    for i in range(len(prime_numbers)):
        for j in range(i+1, len(prime_numbers)):
            for k in range(j+1, len(prime_numbers)):
                if prime_numbers[i] + prime_numbers[j] + prime_numbers[k] == 52:
                    prime_combinations.append((prime_numbers[i], prime_numbers[j], prime_numbers[k]))

    # Step 3: Calculate the product for each combination and return the one that matches the polynomial
    for p, q, r in prime_combinations:
        if p * q * r == 581:
            return p * q * r
    return -1  # If no such combination exists

