    3. Loop through all numbers starting from 2.
    4. If a number is prime, calculate $f(n)$ and check if $f(f(n))$ is also prime.
    5. If it is, return the number.
    6. Return the smallest bouncy prime found.
    '''
    def sum_of_divisors(n):
        sum = 1  # 1 is always a divisor
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                sum += i
                if i != n // i:  # Avoid double counting square roots
                    sum += n // i
        return sum

    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    # Start from 2, the smallest prime number
    n = 2
    while True:
        if is_prime(n):
            f_n = sum_of_divisors(n)
            if is_prime(f_n):
                f_f_n = sum_of_divisors(f_n)
                if is_prime(f_f_n):
                    return n
        n += 1

