def solution():
    '''
    Create a function solution that returns the answer of the following question: What is the greatest prime factor of 3105? 

    Let's think step by step.
    1. Create a helper function to check if a number is prime.
    2. Start from the smallest prime number (2) and check if it divides 3105.
    3. If it does, divide 3105 by this prime number and continue the process with the quotient.
    4. Repeat the process with the next prime number if the current one doesn't divide 3105.
    5. Continue until the quotient is a prime number.
    6. Return the last prime number used in the division process, which will be the greatest prime factor of 3105.
    7. If the input number is less than 2, return an appropriate message as prime factors are not defined for numbers less than 2.
    '''
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    def greatest_prime_factor(n):
        if n < 2:
            return "Prime factors are not defined for numbers less than 2."

        factor = 2
        while factor * factor <= n:
            if n % factor == 0:
                n //= factor
            else:
                factor += 1
        return n if is_prime(n) else factor

    return greatest_prime_factor(3105)

