import operator
import re

def evaluate_expression(expression):
    """Evaluate the given arithmetic expression."""
    # Define the operators and their precedence
    operators = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': operator.truediv
    }

    # Split the expression into numbers and operators
    tokens = re.findall(r'\d+|\+|\-|\*|\/', expression)

    # Evaluate the expression using the Shunting Yard algorithm
    output_queue = []
    operator_stack = []
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}

    for token in tokens:
        if token.isdigit():
            output_queue.append(int(token))
        elif token in operators:
            while operator_stack and operator_stack[-1] in operators and precedence[operator_stack[-1]] >= precedence[token]:
                output_queue.append(operator_stack.pop())
            operator_stack.append(token)

    while operator_stack:
        output_queue.append(operator_stack.pop())

    # Evaluate the postfix expression
    result = output_queue[0]
    for token in output_queue[1:]:
        if token in operators:
            operand2 = result
            operand1 = output_queue.pop(output_queue.index(token) - 1)
            result = operators[token](operand1, operand2)
        else:
            result = token

    return result

