from math import sqrt, isqrt

def solution():
    '''
    Create a function solution that returns the answer of the following question: Simplify $\sqrt{192}$. 

    Let's think step by step.
    1. Factorize the number under the square root into its prime factors.
    2. Pair the prime factors.
    3. For each pair, take one factor out of the square root.
    4. Multiply the factors outside the square root.
    5. Return the result.
    6. Please import inside the function.
    7. If the number under the square root is a perfect square, return the square root directly.
    8. If the number under the square root is 1, return 1.
    9. If the number under the square root is negative, return "Not a real number".
    '''
    def prime_factors(n):
        i = 2
        factors = []
        while i * i <= n:
            if n % i:
                i += 1
            else:
                n //= i
                factors.append(i)
        if n > 1:
            factors.append(n)
        return factors

    def simplify_sqrt(n):
        if n < 0:
            return "Not a real number"
        elif n == 1:
            return 1
        else:
            factors = prime_factors(n)
            sqrt_n = sqrt(n)
            pairs = {}
            for factor in factors:
                if factor in pairs:
                    pairs[factor] += 1
                else:
                    pairs[factor] = 1

            result = 1
            for factor, count in pairs.items():
                if count >= 2:
                    result *= factor
                    count -= 2
                if count > 0:
                    result *= sqrt(factor)

            return result

    return simplify_sqrt(192)

