    '''
    Create a function solution that returns the answer of the following question: Simplify $\sqrt{32670}$. 

    Let's think step by step.
    1. Factorize the number under the square root to find its prime factors.
    2. Pair the prime factors and take one from each pair out of the square root.
    3. Multiply the numbers outside the square root and leave the unpaired factors inside the square root.
    4. Return the simplified form of the square root.
    5. Please import inside the function if necessary.
    '''
    # Step 1: Factorize the number under the square root to find its prime factors
    def prime_factors(n):
        i = 2
        factors = []
        while i * i <= n:
            if n % i:
                i += 1
            else:
                n //= i
                factors.append(i)
        if n > 1:
            factors.append(n)
        return factors

    # Step 2: Pair the prime factors and take one from each pair out of the square root
    factors = prime_factors(32670)
    pairs = {}
    for factor in factors:
        if factor in pairs:
            pairs[factor] += 1
        else:
            pairs[factor] = 1

    # Step 3: Multiply the numbers outside the square root and leave the unpaired factors inside the square root
    outside_sqrt = 1
    inside_sqrt = 1
    for factor, count in pairs.items():
        if count % 2 == 0:
            outside_sqrt *= factor
        else:
            inside_sqrt *= factor

    # Step 4: Return the simplified form of the square root
    return f"{outside_sqrt * sqrt(inside_sqrt)}"

