    magnitude_XZ = ((Z[0] - X[0])**2 + (Z[1] - X[1])**2)**0.5
    cosine_angle = dot_product / (magnitude_XY * magnitude_XZ)

    # Step 3: Calculate the angle in degrees using the arccosine function.
    angle_in_radians = math.acos(cosine_angle)
    angle_in_degrees = math.degrees(angle_in_radians)

